// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amt, uint256 extra) public {
        amt = bound(amt, 1, 1e30);
        extra = bound(extra, 1, 1e30);

        Attacker a = new Attacker(c);
        vm.deal(address(a), amt + extra);

        // Attacker deposits amt, then attempts withdrawal. During the withdrawal's
        // ETH payout its fallback re-enters addToBalance(extra); if that re-entry
        // reverts the fallback reverts, so the whole withdrawal reverts.
        a.attack(amt, extra);

        // Reference: guard makes re-entry revert -> withdrawal reverts -> balance
        // stays amt. Mutant: re-entry succeeds -> withdrawal completes and zeroes
        // the (re-deposited) balance -> balance is 0.
        assertTrue(c.getBalance(address(a)) == amt);
    }
}

contract Attacker {
    Reentrance c;

    constructor(Reentrance _c) { c = _c; }

    function attack(uint256 amt, uint256 extra) external {
        c.addToBalance{value: amt}();
        try c.withdrawBalance() {
            // withdrawal succeeded (mutant path)
        } catch {
            // withdrawal reverted because re-entry reverted (reference path)
        }
    }

    fallback() external payable {
        (bool ok, ) = address(c).call{value: msg.value > 0 ? 0 : 0}("");
        ok; // silence warnings
        (bool ok2, ) = address(c).call(
            abi.encodeWithSignature("addToBalance()")
        );
        if (!ok2) {
            revert();
        }
    }

    receive() external payable {
        c.addToBalance{value: extra_}();
    }

    uint256 extra_;

    function setExtra(uint256 e) external { extra_ = e; }
}
